-- Emails for accounts created from the admin panel (features/admin/create-user.server.ts):
--   user_invite      — set-your-password link (invite method)
--   account_created  — login details when the admin sets the password and ticks "email the details"
insert into public.email_templates (key, name_ar, name_en, subject_ar, subject_en, html_ar, html_en, variables) values
('user_invite', 'دعوة لحساب جديد', 'Account invitation',
 'تمت دعوتك إلى {{site_name}}', 'You''re invited to {{site_name}}',
 '<!doctype html><html lang="ar" dir="rtl"><body style="margin:0;background:#FAFAFA;font-family:Tahoma,Arial,sans-serif;color:#1F2937;"><div style="max-width:560px;margin:0 auto;padding:32px 16px;"><div style="background:#FFFFFF;border:1px solid #E5E7EB;border-radius:12px;padding:32px;"><h1 style="margin:0 0 8px;font-size:20px;color:#BE0404;">أهلًا {{name}}،</h1><p style="margin:0 0 16px;font-size:14px;line-height:1.7;">أنشأ فريق {{site_name}} حسابًا لك بصفة <strong>{{role}}</strong> على البريد {{email}}. اضغط الزر لاختيار كلمة المرور وتفعيل حسابك.</p><a href="{{invite_url}}" style="display:inline-block;background:#BE0404;color:#FFFFFF;text-decoration:none;font-size:14px;font-weight:bold;padding:12px 24px;border-radius:8px;">اختيار كلمة المرور</a><p style="margin:16px 0 0;font-size:12px;line-height:1.7;color:#6B7280;">الرابط صالح لفترة محدودة. إن لم تكن تتوقع هذه الرسالة فتجاهلها.</p></div><p style="margin:16px 0 0;font-size:12px;color:#6B7280;text-align:center;">&copy; {{site_name}} — جميع الحقوق محفوظة.</p></div></body></html>',
 '<!doctype html><html lang="en" dir="ltr"><body style="margin:0;background:#FAFAFA;font-family:Arial,sans-serif;color:#1F2937;"><div style="max-width:560px;margin:0 auto;padding:32px 16px;"><div style="background:#FFFFFF;border:1px solid #E5E7EB;border-radius:12px;padding:32px;"><h1 style="margin:0 0 8px;font-size:20px;color:#BE0404;">Hello {{name}},</h1><p style="margin:0 0 16px;font-size:14px;line-height:1.7;">The {{site_name}} team created a <strong>{{role}}</strong> account for you ({{email}}). Choose your password to activate it.</p><a href="{{invite_url}}" style="display:inline-block;background:#BE0404;color:#FFFFFF;text-decoration:none;font-size:14px;font-weight:bold;padding:12px 24px;border-radius:8px;">Choose a password</a><p style="margin:16px 0 0;font-size:12px;line-height:1.7;color:#6B7280;">The link expires after a while. If you weren''t expecting this email, ignore it.</p></div><p style="margin:16px 0 0;font-size:12px;color:#6B7280;text-align:center;">&copy; {{site_name}} — All rights reserved.</p></div></body></html>',
 '["name","email","role","invite_url","site_name","site_url"]'::jsonb),
('account_created', 'بيانات حساب جديد', 'New account details',
 'حسابك في {{site_name}} جاهز', 'Your {{site_name}} account is ready',
 '<!doctype html><html lang="ar" dir="rtl"><body style="margin:0;background:#FAFAFA;font-family:Tahoma,Arial,sans-serif;color:#1F2937;"><div style="max-width:560px;margin:0 auto;padding:32px 16px;"><div style="background:#FFFFFF;border:1px solid #E5E7EB;border-radius:12px;padding:32px;"><h1 style="margin:0 0 8px;font-size:20px;color:#BE0404;">أهلًا {{name}}،</h1><p style="margin:0 0 16px;font-size:14px;line-height:1.7;">أنشأ فريق {{site_name}} حسابًا لك بصفة <strong>{{role}}</strong>. بيانات الدخول:</p><p style="margin:0 0 16px;font-size:14px;line-height:1.9;background:#F9FAFB;border:1px solid #E5E7EB;border-radius:8px;padding:12px 16px;">البريد: <span dir="ltr">{{email}}</span><br>كلمة المرور المؤقتة: <span dir="ltr" style="font-family:monospace;">{{password}}</span></p><a href="{{login_url}}" style="display:inline-block;background:#BE0404;color:#FFFFFF;text-decoration:none;font-size:14px;font-weight:bold;padding:12px 24px;border-radius:8px;">تسجيل الدخول</a><p style="margin:16px 0 0;font-size:12px;line-height:1.7;color:#6B7280;">ننصحك بتغيير كلمة المرور من صفحة حسابك بعد أول تسجيل دخول.</p></div><p style="margin:16px 0 0;font-size:12px;color:#6B7280;text-align:center;">&copy; {{site_name}} — جميع الحقوق محفوظة.</p></div></body></html>',
 '<!doctype html><html lang="en" dir="ltr"><body style="margin:0;background:#FAFAFA;font-family:Arial,sans-serif;color:#1F2937;"><div style="max-width:560px;margin:0 auto;padding:32px 16px;"><div style="background:#FFFFFF;border:1px solid #E5E7EB;border-radius:12px;padding:32px;"><h1 style="margin:0 0 8px;font-size:20px;color:#BE0404;">Hello {{name}},</h1><p style="margin:0 0 16px;font-size:14px;line-height:1.7;">The {{site_name}} team created a <strong>{{role}}</strong> account for you. Your sign-in details:</p><p style="margin:0 0 16px;font-size:14px;line-height:1.9;background:#F9FAFB;border:1px solid #E5E7EB;border-radius:8px;padding:12px 16px;">Email: {{email}}<br>Temporary password: <span style="font-family:monospace;">{{password}}</span></p><a href="{{login_url}}" style="display:inline-block;background:#BE0404;color:#FFFFFF;text-decoration:none;font-size:14px;font-weight:bold;padding:12px 24px;border-radius:8px;">Sign in</a><p style="margin:16px 0 0;font-size:12px;line-height:1.7;color:#6B7280;">Please change the password from your account page after your first sign-in.</p></div><p style="margin:16px 0 0;font-size:12px;color:#6B7280;text-align:center;">&copy; {{site_name}} — All rights reserved.</p></div></body></html>',
 '["name","email","role","password","login_url","site_name","site_url"]'::jsonb)
on conflict (key) do nothing;
